    const ultimo = (tool) => { const es = tool === 'gestionar_turno' ? esGestion : (t) => t === tool; for (let i = r.length - 1; i >= 0; i--) if (es(r[i].tool) && (r[i].texto || r[i].pregunta || r[i].error_tecnico || r[i].derivar)) return r[i]; return null; };
