      texto: '', estado: 'nada', fuera_de_alcance: false, urgencia: false, derivar: null, error_tecnico: false, datos_pago: false,
      texto_libre_descartado: (!cod && textoModelo(a.output).trim()) ? lim(textoModelo(a.output), 300) : null };
